CREATE TABLE friend_requests(id UUID PRIMARY KEY,requester_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,addressee_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,status VARCHAR(16) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(requester_id,addressee_id));
CREATE TABLE friendships(user_low UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,user_high UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(user_low,user_high),CHECK(user_low<user_high));
CREATE TABLE user_devices(id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,push_token VARCHAR(512) NOT NULL UNIQUE,platform VARCHAR(16) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
